// Adaptive prototype: only fields relevant to the selected purpose are required.
const originalRecord=record;record=function(){const r=originalRecord();r.openings??=[];r.courses??=[];return r};
const purposes={teacher:['Find a job','Offer tuition / coaching / training'],institution:['Hire teachers / professors','Promote admissions','Training association / partnership'],training:['Individual learner enrolment','Institutional partnerships']};
function selectedPurposes(){return record().fields.purposes||[]}
function hasPurpose(p){return selectedPurposes().includes(p)}
function steps(){const r=state.role;return [{id:'basics',title:'Account & authorised contact'},...(r==='learner'?[]:[{id:'purpose',title:'Your purpose'}]),{id:'background',title:r==='training'?'Provider expertise':r==='institution'?'Institution & programmes':'Background & goals'},...(r==='institution'?[]:[{id:'skills',title:r==='training'?'Skills offered & expertise':'Skills'}]),...(r==='institution'&&hasPurpose('Hire teachers / professors')?[{id:'openings',title:'Job openings & required skills'}]:[]),...(r==='training'?[{id:'courses',title:'Detailed courses'}]:[]),{id:'preferences',title:r==='institution'?'Admissions & partnerships':'Preferences & availability'},...(r==='learner'?[]:[{id:'evidence',title:'Relevant evidence'}]),{id:'consent',title:'Contact & consent'},{id:'review',title:'Review & complete'}]}
const courseMap={Preschool:['Playgroup','Nursery','LKG','UKG'],School:['Primary (Classes 1–5)','Middle (Classes 6–8)','Secondary (Classes 9–10)','Higher secondary (Classes 11–12)'],College:['BA','B.Sc.','B.Com.','BBA','BCA','B.E. / B.Tech.','B.Ed.','MA','M.Sc.','MBA','MCA','M.E. / M.Tech.','Diploma'],University:['Undergraduate','Postgraduate','Doctoral','Diploma','Certificate'],Other:['Certificate','Diploma','Other programme']};
const originalFieldHTML=fieldHTML;fieldHTML=function(f){if(f.type!=='multi')return originalFieldHTML(f);const value=record().fields[f.key]||[];return `<fieldset class="full choice-group"><legend>${f.label}${f.required?' *':''}</legend>${f.options.map(v=>`<label class="check-row"><input type="checkbox" name="${f.key}" value="${esc(v)}" ${value.includes(v)?'checked':''}><span>${esc(v)}</span></label>`).join('')}</fieldset>`};
function authFields(){const adult=state.role==='learner';return [field('authorisedPerson',adult?'Responsible adult / authorised guardian name':'Authorised contact person','text',[],true),field('contactDesignation',adult?'Relationship / capacity':'Designation / role','text',[],true),field('officialEmail',adult?'Adult / guardian contact email':'Working / official email','email',[],true),field('officialPhone',adult?'Adult / guardian contact phone':'Official phone with country code','tel',[],true),field('whatsapp','WhatsApp contact number (optional)'),field('alternateContact','Alternative authorised contact (optional)')]}
function adaptiveFields(id){let r=state.role,f=record().fields,qs=questions[r];if(id==='basics')return [...common.filter(x=>!['phone'].includes(x.key)),...(r==='institution'?[qs.background.find(x=>x.key==='institutionType')]:[]),...authFields()];if(id==='background'){
 if(r==='institution')return [...qs.background.filter(x=>!['institutionType','contactPerson','designation','programmes'].includes(x.key)),field('programmeSelection','Grades / courses offered','multi',courseMap[f.institutionType]||courseMap.Other,true),field('programmeSpecialisations','Departments / course specialisations','textarea',[],['College','University'].includes(f.institutionType)),field('programmeOther','Other programmes / custom course names','textarea')];
 if(r==='training')return [...qs.background.filter(x=>!['contactPerson','designation','programmes'].includes(x.key)),field('expertiseAreas','Areas of expertise and practical strengths','textarea',[],true),field('trainerExpertise','Trainer qualifications and domain experience','textarea',[],true)];
 if(r==='teacher')return qs.background.filter(x=>hasPurpose('Find a job')||!['teacherQualification','employment','currentRole','boards'].includes(x.key));return qs.background;
 }if(id==='preferences'){
 if(r==='learner')return qs.preferences;
 if(r==='teacher'){const jobs=hasPurpose('Find a job'),services=hasPurpose('Offer tuition / coaching / training');return qs.preferences.filter(x=>x.key!=='intent'&&(!['jobType','relocate','notice','salary'].includes(x.key)||jobs)&&(!['serviceTypes','fee','feeUnit'].includes(x.key)||services)).map(x=>({...x,required:x.required||(services&&['serviceTypes','fee','feeUnit'].includes(x.key))})).concat(services?[field('serviceAudience','Service audience / age groups','text',[],true),field('serviceDuration','Session duration / frequency','text',[],true)]:[])}
 if(r==='institution'){let a=[];if(hasPurpose('Promote admissions'))a.push(...qs.preferences.filter(x=>['admissionGrades','admissionCycle','feeRange','audience','admissionProcess'].includes(x.key)).map(x=>({...x,required:true})),field('admissionSeats','Seats available / intake capacity','text',[],true),field('admissionDeadline','Admission closing date (if known)','date'));if(hasPurpose('Training association / partnership'))a.push(field('partnerNeed','Training / partnership objective','textarea',[],true),field('partnerSkills','Skills / programme areas needed','textarea',[],true),field('partnerAudience','Participants / departments','text',[],true),field('partnerCount','Expected participants','number',[],true),field('partnerMode','Preferred delivery','select',['Online','On campus','Hybrid'],true),field('partnerBudget','Budget range and period','text',[],true),field('partnerTimeline','Training timeline','text',[],true),field('partnerModel','Association model','select',['One-time workshop','Recurring programme','Long-term training partnership','Open to proposals'],true));return a;}
 if(r==='training')return qs.preferences.filter(x=>x.key!=='intent'&&(!['customise','institutionTypes','contractSize','travel'].includes(x.key)||hasPurpose('Institutional partnerships'))&&(!['start'].includes(x.key)||hasPurpose('Individual learner enrolment')));
 }if(id==='consent')return [field('source','How did you hear about Talind?','select',['Search engine','Social media','Referral','Institution','Event','Advertisement','Other'],true),field('sourceDetail','Referral / campaign details'),field('decisionRole','Authorised person’s decision role','select',r==='learner'?['Self / adult learner','Parent / guardian']:['Decision maker','Authorised coordinator','Recommender'],true),field('contactChannel','Preferred contact channel','select',['Email','Phone','WhatsApp'],true),field('contactTime','Preferred contact time','text',[],true),field('purchaseTimeline','Decision timeline','select',['Immediately','This month','Within three months','Exploring'],true)];return []}
function purposeHTML(){return `<p class="muted">Select every purpose that applies. Questions and required fields will adapt to your selection.</p><div class="purpose-options">${purposes[state.role].map(p=>`<label class="check-row"><input type="checkbox" name="purposes" value="${p}" ${hasPurpose(p)?'checked':''}><span>${p}</span></label>`).join('')}</div><p class="bottom-note">${state.role==='teacher'?'Job seeking is free. Offering services requires a paid membership.':'Institution and training-provider access is paid. No payment is collected in this sample.'}</p>`}
const arrayFields=['purposes','programmeSelection'];
saveFields=function(){const form=$('#registration-form');if(!form)return;const d=new FormData(form),id=steps()[registration.step]?.id;d.forEach((v,k)=>{if(!arrayFields.includes(k))record().fields[k]=v});for(const key of arrayFields){if((key==='purposes'&&id==='purpose')||(key==='programmeSelection'&&id==='background'&&state.role==='institution'))record().fields[key]=d.getAll(key)}if(id==='consent')for(const k of ['accuracy','guardian','authority','marketingEmail','marketingPhone','marketingWhatsapp','contactShare'])record().fields[k]=!!form.elements[k]?.checked;record().complete=false};
function validateFields(fields){const m=[],f=record().fields;for(const q of fields){const v=f[q.key];if(q.required&&(!v||(Array.isArray(v)?!v.length:!String(v).trim())))m.push(q.label);if(v&&q.type==='email'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))m.push('Valid '+q.label);if(v!==undefined&&v!==''&&q.type==='number'&&(!Number.isFinite(Number(v))||Number(v)<0))m.push('Valid '+q.label)}return m}
missingFields=function(){let m=[];for(const s of steps())m.push(...validateFields(adaptiveFields(s.id)));if(state.role!=='learner'&&!selectedPurposes().length)m.push('At least one purpose');if(state.role!=='institution'&&!record().skills.length)m.push('At least one skill');if(state.role==='institution'&&hasPurpose('Hire teachers / professors')&&!record().openings.length)m.push('At least one job opening');if(state.role==='training'&&!record().courses.length)m.push('At least one detailed course');if(!record().fields.accuracy)m.push('Accuracy confirmation');if(!record().fields.authority)m.push('Authorised contact confirmation');if(state.role==='learner'&&!record().fields.guardian)m.push('Adult / guardian confirmation');if(state.role==='learner'&&record().fields.accountFor==='Adult learner (18+)'&&record().fields.ageBand!=='18+')m.push('Guardian account for a learner under 18');return m};
currentValid=function(){const form=$('#registration-form');if(form&&!form.reportValidity())return false;saveFields();const id=steps()[registration.step].id;let msg=validateFields(adaptiveFields(id));if(id==='purpose'&&!selectedPurposes().length)msg.push('Choose at least one purpose');if(id==='skills'&&!record().skills.length)msg.push('Add at least one skill');if(id==='openings'&&!record().openings.length)msg.push('Add at least one opening');if(id==='courses'&&!record().courses.length)msg.push('Add at least one course');if(msg.length){toast(msg[0]);return false}return true};
const jobFields=[field('title','Job title','text',[],true),field('department','Subject / department','text',[],true),field('level','Grades / course level','text',[],true),field('vacancies','Number of vacancies','number',[],true),field('qualification','Required qualification','text',[],true),field('experience','Minimum experience (years)','number',[],true),field('employment','Employment type','select',['Full time','Part time','Contract','Visiting faculty'],true),field('location','Job location / online','text',[],true),field('salary','Salary range and period','text',[],true),field('joining','Expected joining / timeline','text',[],true),field('description','Responsibilities and expectations','textarea',[],true)];
const courseFields=[field('title','Course / programme title','text',[],true),field('category','Category','select',['Subject tuition','Skill development','NEET','JEE','Teacher development','Professional training','Other'],true),field('audience','Target learners / age group','text',[],true),field('level','Course level','select',['Beginner','Intermediate','Advanced','All levels'],true),field('prerequisites','Prerequisites (or none)','textarea',[],true),field('syllabus','Syllabus / modules covered','textarea',[],true),field('outcomes','Learning outcomes','textarea',[],true),field('duration','Total duration and teaching hours','text',[],true),field('schedule','Days, timing and frequency','text',[],true),field('mode','Delivery mode','select',['Online','In person','Hybrid'],true),field('location','Location / online platform','text',[],true),field('batch','Batch size / capacity','number',[],true),field('start','Next start date / rolling intake','text',[],true),field('fee','Fee, currency, billing unit and inclusions','text',[],true),field('trainer','Trainer name / qualifications / expertise','textarea',[],true),field('assessment','Assessment method','textarea',[],true),field('certificate','Certificate / awarding body (or none)','text',[],true),field('demo','Trial / demo availability','select',['Available','Not available','On request'],true),field('customisation','Institutional customisation options (or none)','textarea',[],true)];
let editorSkills=[];
function builderField(q,value=''){const o=q.type==='select'?`<select id="entry-${q.key}" data-required="${q.required}">${q.options.map(x=>`<option>${esc(x)}</option>`).join('')}</select>`:q.type==='textarea'?`<textarea id="entry-${q.key}" maxlength="2500"></textarea>`:`<input id="entry-${q.key}" type="${q.type}" ${q.type==='number'?'min="0"':''} maxlength="500">`;return `<label class="${q.type==='textarea'?'full':''}">${q.label} *${o}</label>`}
function entriesHTML(kind){const list=record()[kind],jobs=kind==='openings';return `<p class="muted">${jobs?'Create each vacancy with its own qualification requirements and skills.':'List each course separately, including syllabus, outcomes, fees and trainer expertise.'} Add multiple entries as needed.</p><div>${list.map((e,i)=>`<div class="skill-row"><div><strong>${esc(e.title)}</strong><p>${esc(jobs?e.department:e.category)} · ${esc(jobs?e.employment:e.duration)}</p><div class="tags">${e.skills.map(s=>`<span>${esc(s)}</span>`).join('')}</div></div><button type="button" class="btn outline" onclick="removeEntry('${kind}',${i})">Remove</button></div>`).join('')}</div><details class="entry-builder" ${list.length?'':'open'}><summary>+ Add ${jobs?'job opening':'detailed course'}</summary><div class="fields">${(jobs?jobFields:courseFields).map(q=>builderField(q)).join('')}</div><h3>${jobs?'Skills required for this opening':'Skills taught in this course'}</h3><div class="skill-builder"><label>Choose a skill<select id="entry-skill-pick"><option value="">Choose a skill</option>${catalog.map(s=>`<option>${s}</option>`).join('')}</select></label><label>Or enter a custom skill<input id="entry-skill-custom" maxlength="100"></label></div><button type="button" class="btn light" onclick="addEntrySkill()">+ Add skill</button><div class="tags" id="entry-skills" aria-live="polite"></div><p class="form-error" id="entry-error" role="alert"></p><button type="button" class="btn" onclick="saveEntry('${kind}')">Save ${jobs?'job opening':'course'}</button></details>`}
function addEntrySkill(){const name=$('#entry-skill-custom').value.trim()||$('#entry-skill-pick').value;if(!name)return toast('Choose or type a skill.');if(!editorSkills.some(x=>x.toLowerCase()===name.toLowerCase()))editorSkills.push(name);$('#entry-skills').innerHTML=editorSkills.map((s,i)=>`<button class="chip" type="button" onclick="editorSkills.splice(${i},1);refreshEntrySkills()">${esc(s)} ×</button>`).join('');$('#entry-skill-custom').value=''}
function refreshEntrySkills(){$('#entry-skills').innerHTML=editorSkills.map((s,i)=>`<button class="chip" type="button" onclick="editorSkills.splice(${i},1);refreshEntrySkills()">${esc(s)} ×</button>`).join('')}
function saveEntry(kind){const fields=kind==='openings'?jobFields:courseFields,obj={};for(const q of fields){const el=$('#entry-'+q.key),v=el.value.trim();if(!v||!el.reportValidity()){$('#entry-error').textContent='Please complete: '+q.label;el.focus();return}obj[q.key]=v}if(!editorSkills.length){$('#entry-error').textContent='Add at least one relevant skill.';return}obj.skills=[...editorSkills];record()[kind].push(obj);record().complete=false;editorSkills=[];profile();toast('Sample '+(kind==='openings'?'opening':'course')+' added.')}
function removeEntry(kind,i){record()[kind].splice(i,1);record().complete=false;profile()}
const baseEvidenceHTML=evidenceHTML;evidenceHTML=function(){if(state.role==='learner')return '';let types=[],links=[];if(state.role==='teacher'){if(hasPurpose('Find a job'))types.push('Résumé / CV','Qualification certificate','Experience letter');if(hasPurpose('Offer tuition / coaching / training'))types.push('Coaching portfolio','Skill certificate','Workshop outline');links=['Teaching / coaching demo','Skill demonstration','Portfolio website','Certificate verification page']}if(state.role==='institution'){if(hasPurpose('Hire teachers / professors'))types.push('Recruitment brochure','Job description');if(hasPurpose('Promote admissions'))types.push('Institution brochure','Affiliation certificate','Programme prospectus','Fee information');if(hasPurpose('Training association / partnership'))types.push('Training requirement brief','Partnership proposal');links=['Official website','Campus tour','Programme information','Partnership information']}if(state.role==='training'){types=['Trainer résumé','Trainer qualification','Course brochure','Skill / accreditation certificate'];if(hasPurpose('Institutional partnerships'))types.push('Institutional proposal','Past training portfolio');links=['Training demo','Trainer introduction','Course outline','Certificate verification page']}
const html=baseEvidenceHTML();return html.replace(/(<select id="evidence-kind">)[\s\S]*?(<\/select>)/,`$1${types.map(s=>`<option>${s}</option>`).join('')}$2`).replace(/(<select id="link-kind">)[\s\S]*?(<\/select>)/,`$1${links.map(s=>`<option>${s}</option>`).join('')}$2`)};
function contextSummary(){return state.role==='learner'?'learning and admission enquiries':selectedPurposes().join(', ').toLowerCase()||'your selected services'}
consentHTML=function(){return `<p class="muted">Contact preferences for ${esc(contextSummary())}. Communications should go to the authorised adult or representative listed in your profile.</p><div class="fields">${adaptiveFields('consent').map(fieldHTML).join('')}</div>${checkbox('accuracy','I confirm that my profile information is accurate.',true)}${checkbox('authority',state.role==='learner'?'I am the adult learner or authorised parent / guardian for this account.':'I am authorised to represent this person or organisation and handle the selected enquiries.',true)}${state.role==='learner'?checkbox('guardian','I am 18 or older and will manage contact on behalf of any learner under 18.',true):''}${checkbox('contactShare','Share the authorised contact details only when I initiate or respond to a relevant enquiry.')}<h3>Optional updates</h3><p class="muted">Updates relevant to ${esc(contextSummary())}. These opt-ins are optional and start unchecked.</p>${checkbox('marketingEmail','Receive relevant updates by email.')}${checkbox('marketingPhone','Receive relevant offers by phone.')}${checkbox('marketingWhatsapp','Receive relevant updates on WhatsApp.')}<p class="bottom-note">The sample sends no communications. Learner and parent evidence is not requested.</p>`};
function reviewAdaptive(){const r=record(),missing=missingFields();return `<div class="notice ${missing.length?'':'success'}">${missing.length?missing.length+' required items still need attention.':'Required information is complete.'}</div>${steps().filter(s=>!['review','evidence'].includes(s.id)).map(s=>`<section class="review-section"><div class="section-top"><h3>${s.title}</h3><button type="button" class="btn outline" onclick="jumpStep(${steps().findIndex(x=>x.id===s.id)})">Edit</button></div>${s.id==='purpose'?esc(selectedPurposes().join(', ')):s.id==='skills'?r.skills.map(x=>`<p>${esc(x.name)} · ${esc(x.purpose)} · ${x.level}</p>`).join(''):['openings','courses'].includes(s.id)?r[s.id].map(x=>`<details><summary>${esc(x.title)}</summary><dl>${Object.entries(x).map(([k,v])=>`<div><dt>${esc((s.id==='openings'?jobFields:courseFields).find(f=>f.key===k)?.label||k)}</dt><dd>${esc(Array.isArray(v)?v.join(', '):v)}</dd></div>`).join('')}</dl></details>`).join(''):`<dl>${adaptiveFields(s.id).map(q=>`<div><dt>${q.label}</dt><dd>${esc(Array.isArray(r.fields[q.key])?r.fields[q.key].join(', '):r.fields[q.key]||'Not provided')}</dd></div>`).join('')}</dl>`}</section>`).join('')}${state.role!=='learner'?`<p>${r.evidence.length} local document(s) · ${r.links.length} evidence link(s). Evidence is optional and unverified.</p>`:''}<p>Marketing opt-ins: ${['marketingEmail','marketingPhone','marketingWhatsapp'].filter(k=>r.fields[k]).map(k=>k.replace('marketing','')).join(', ')||'None'}</p>${missing.length?`<p class="form-error">Missing: ${missing.map(esc).join('; ')}</p>`:''}<button type="button" class="btn" onclick="completeProfile()">Complete sample registration</button>`}
profile=function(){let list=steps();registration.step=Math.min(registration.step,list.length-1);const n=registration.step,s=list[n];editorSkills=[];$('#main').innerHTML=intro('PURPOSE-BASED REGISTRATION',record().complete?'Your profile is ready.':'Build the profile you need.',`${roleNames[state.role]} · Required fields adapt to your selected purpose.`)+`<div class="notice">Sample only. Use fictional details. Entries and selected files reset on refresh. ${state.role==='learner'?'No evidence or documents are requested for students and parents.':''}</div><div class="onboard-layout"><div class="step-nav">${list.map((x,i)=>`<button type="button" class="step-button ${n===i?'active':''}" onclick="jumpStep(${i})"><span>${i+1}</span>${x.title}</button>`).join('')}</div><section class="panel onboarding-panel"><span class="eyebrow">STEP ${n+1} OF ${list.length}</span><h2>${s.title}</h2><form id="registration-form">${s.id==='purpose'?purposeHTML():s.id==='skills'?skillsHTML():s.id==='openings'||s.id==='courses'?entriesHTML(s.id):s.id==='evidence'?evidenceHTML():s.id==='consent'?consentHTML():s.id==='review'?reviewAdaptive():`<div class="fields">${adaptiveFields(s.id).map(fieldHTML).join('')}</div>${s.id==='preferences'&&!adaptiveFields(s.id).length?'<p class="muted">Your selected hiring purpose is covered under Job openings. You can continue.</p>':''}`}<div class="step-actions">${n?'<button type="button" class="btn outline" onclick="backStep()">Back</button>':''}${n<list.length-1?'<button class="btn" type="submit">Save & continue →</button>':''}<button type="button" class="btn light" onclick="saveFields();toast('Draft retained for this session.')">Keep session draft</button></div></form></section></div>`;$('#registration-form').onsubmit=e=>{e.preventDefault();advance()};const type=$('#registration-form select[name="institutionType"]');if(type)type.onchange=()=>{saveFields();record().fields.programmeSelection=[];profile()}}
advance=function(){if(!currentValid())return;registration.step=Math.min(registration.step+1,steps().length-1);profile();window.scrollTo(0,0)};
jumpStep=function(n){const id=steps()[n]?.id;saveFields();registration.step=Math.max(0,steps().findIndex(s=>s.id===id));profile()};
openEvidence=function(){const i=steps().findIndex(s=>s.id==='evidence');if(i>=0){registration.step=i;navigate('profile')}};
function startInstitutionPurpose(p){state.role='institution';$('#role').value='institution';if(!hasPurpose(p))record().fields.purposes=[...selectedPurposes(),p];registration.step=steps().findIndex(s=>s.id===(p==='Hire teachers / professors'?'openings':'preferences'));navigate('profile')}
const previousWorkspace=workspace;workspace=function(){previousWorkspace();if(state.role==='institution')$('#main').insertAdjacentHTML('afterbegin',`<section class="panel"><h2>What would your institution like to do?</h2><div class="workspace-links" style="margin-top:18px"><button class="btn" onclick="navigate('explore')">Discover teachers / professors</button><button class="btn light" onclick="startInstitutionPurpose('Hire teachers / professors')">Post a job opening</button><button class="btn light" onclick="startInstitutionPurpose('Promote admissions')">Admission promotions</button><button class="btn light" onclick="startInstitutionPurpose('Training association / partnership')">Find training partners</button></div><p class="muted">Select one or more purposes; each has its own questions and contact preferences.</p></section>`)};
